CREATE TABLE auctions (id VARCHAR(64) PRIMARY KEY, status VARCHAR(16) NOT NULL, start_price BIGINT NOT NULL, min_increment BIGINT NOT NULL, current_price BIGINT NOT NULL, leader_id VARCHAR(64), ends_at TIMESTAMP(6), extension_count INT NOT NULL DEFAULT 0, seq BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6));
CREATE TABLE auction_participants (auction_id VARCHAR(64) NOT NULL, user_id VARCHAR(64) NOT NULL, participant_type VARCHAR(16) NOT NULL, joined_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY (auction_id,user_id));
CREATE TABLE bids (id BIGINT AUTO_INCREMENT PRIMARY KEY, auction_id VARCHAR(64) NOT NULL, user_id VARCHAR(64) NOT NULL, amount BIGINT NOT NULL, request_id VARCHAR(128) NOT NULL, server_seq BIGINT NOT NULL, server_time TIMESTAMP(6) NOT NULL, UNIQUE KEY uk_bid_request (auction_id,user_id,request_id));
CREATE TABLE bid_requests (auction_id VARCHAR(64) NOT NULL, user_id VARCHAR(64) NOT NULL, request_id VARCHAR(128) NOT NULL, result_code VARCHAR(32) NOT NULL, created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY (auction_id,user_id,request_id));
CREATE TABLE settlements (auction_id VARCHAR(64) PRIMARY KEY, winner_id VARCHAR(64), final_price BIGINT NOT NULL, reason VARCHAR(32) NOT NULL, created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6));
CREATE TABLE agent_tokens (id BIGINT AUTO_INCREMENT PRIMARY KEY, token_hash CHAR(64) NOT NULL UNIQUE, agent_user_id VARCHAR(64) NOT NULL, auction_id VARCHAR(64), permissions VARCHAR(128) NOT NULL, expires_at TIMESTAMP(6) NOT NULL, revoked_at TIMESTAMP(6), rate_limit_per_minute INT NOT NULL DEFAULT 60);
